/**
 * Builds `docs/supabase/schema.sql`: every Drizzle migration in one script for
 * the Supabase SQL Editor, plus the bookkeeping rows Drizzle's migrator keeps in
 * `drizzle.__drizzle_migrations`, so a later `pnpm db:migrate` sees the schema as
 * up to date and only applies migrations added after this file was generated.
 *
 * Usage: pnpm db:export-sql          (rewrite the file)
 *        pnpm db:export-sql --check  (exit 1 if the committed file is stale)
 */
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

import { readMigrationFiles } from "drizzle-orm/migrator";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
export const MIGRATIONS_DIR = path.join(ROOT, "drizzle");
export const OUTPUT_FILE = path.join(ROOT, "docs", "supabase", "schema.sql");
export const UPGRADE_FILE = path.join(ROOT, "docs", "supabase", "upgrade.sql");

/** Pure: migrations folder -> script text (no clock, deterministic). */
export function buildSupabaseSql(migrationsFolder: string = MIGRATIONS_DIR): string {
  const migrations = readMigrationFiles({ migrationsFolder });
  const lines: string[] = [];

  lines.push(
    "-- LemmaYard schema for a FRESH Supabase project (SQL Editor -> New query -> paste -> Run).",
    "-- Generated by `pnpm db:export-sql` from drizzle/*.sql; do not edit by hand.",
    `-- Contains ${migrations.length} migrations. It creates the tables, indexes and CHECKs,`,
    "-- enables Row Level Security on every table (no policies: only the owner role the",
    "-- app connects with can read or write) and records the migrations in",
    "-- drizzle.__drizzle_migrations so `pnpm db:migrate` later applies only newer ones.",
    "-- Seed the problems afterwards: run docs/supabase/problems.sql the same way",
    "-- (or DATABASE_URL_DIRECT='<session pooler>' pnpm problems:import).",
    "",
    "BEGIN;",
    "",
    "-- Safety: refuse to run on a database that already has the app's tables.",
    "DO $$",
    "BEGIN",
    "  IF to_regclass('public.users') IS NOT NULL OR to_regclass('drizzle.__drizzle_migrations') IS NOT NULL THEN",
    "    RAISE EXCEPTION 'LemmaYard tables already exist in this database. Use `pnpm db:migrate` instead of this script.';",
    "  END IF;",
    "END $$;",
    "",
  );

  migrations.forEach((m, i) => {
    lines.push(`-- ---- migration ${i}: hash ${m.hash.slice(0, 12)} ----`);
    for (const statement of m.sql) {
      const trimmed = statement.trim();
      if (trimmed) lines.push(trimmed.endsWith(";") ? trimmed : `${trimmed};`, "");
    }
  });

  lines.push(
    "-- ---- Drizzle bookkeeping (same shape the migrator creates) ----",
    'CREATE SCHEMA IF NOT EXISTS "drizzle";',
    "",
    'CREATE TABLE IF NOT EXISTS "drizzle"."__drizzle_migrations" (',
    "  id SERIAL PRIMARY KEY,",
    "  hash text NOT NULL,",
    "  created_at bigint",
    ");",
    "",
    'INSERT INTO "drizzle"."__drizzle_migrations" ("hash", "created_at") VALUES',
    migrations.map((m) => `  ('${m.hash}', ${m.folderMillis})`).join(",\n") + ";",
    "",
    "COMMIT;",
    "",
    "-- Sanity check: expect every table below with rls = true.",
    "SELECT c.relname AS table_name, c.relrowsecurity AS rls",
    "FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace",
    "WHERE n.nspname = 'public' AND c.relkind = 'r'",
    "ORDER BY c.relname;",
    "",
  );

  return lines.join("\n");
}

/**
 * Pure: migrations folder -> script that brings an EXISTING database (created
 * from an older schema.sql or by `pnpm db:migrate`) up to date from the SQL
 * Editor, without credentials. Each migration runs only when its hash is not
 * yet in drizzle.__drizzle_migrations, so the script is safe to re-run and
 * also works on an empty database.
 */
export function buildUpgradeSql(migrationsFolder: string = MIGRATIONS_DIR): string {
  const migrations = readMigrationFiles({ migrationsFolder });
  const lines: string[] = [
    "-- LemmaYard upgrade for a database that already has (some of) the tables:",
    "-- applies only the migrations that are not recorded yet, then records them.",
    "-- Safe to run again. Generated by `pnpm db:export-sql` from drizzle/*.sql; do not edit by hand.",
    `-- Contains ${migrations.length} migrations in total.`,
    "",
    "BEGIN;",
    "",
    'CREATE SCHEMA IF NOT EXISTS "drizzle";',
    'CREATE TABLE IF NOT EXISTS "drizzle"."__drizzle_migrations" (',
    "  id SERIAL PRIMARY KEY,",
    "  hash text NOT NULL,",
    "  created_at bigint",
    ");",
    "",
  ];
  migrations.forEach((m, i) => {
    lines.push(`-- ---- migration ${i}: hash ${m.hash.slice(0, 12)} ----`, "DO $lyup$", "BEGIN");
    lines.push(`  IF NOT EXISTS (SELECT 1 FROM "drizzle"."__drizzle_migrations" WHERE hash = '${m.hash}') THEN`);
    for (const statement of m.sql) {
      const trimmed = statement.trim();
      if (!trimmed) continue;
      if (trimmed.includes("$lymig$")) throw new Error(`migration ${i} contains the reserved quote tag $lymig$`);
      lines.push(`    EXECUTE $lymig$${trimmed}$lymig$;`);
    }
    lines.push(
      `    INSERT INTO "drizzle"."__drizzle_migrations" ("hash", "created_at") VALUES ('${m.hash}', ${m.folderMillis});`,
      "  END IF;",
      "END",
      "$lyup$;",
      "",
    );
  });
  lines.push(
    "COMMIT;",
    "",
    "-- Sanity check: one row per migration.",
    'SELECT count(*) AS migrations_recorded FROM "drizzle"."__drizzle_migrations";',
    "",
  );
  return lines.join("\n");
}

function main() {
  const sql = buildSupabaseSql();
  const upgrade = buildUpgradeSql();
  const targets: [string, string][] = [
    [OUTPUT_FILE, sql],
    [UPGRADE_FILE, upgrade],
  ];
  if (process.argv.includes("--check")) {
    for (const [file, expected] of targets) {
      let current = "";
      try {
        current = readFileSync(file, "utf8");
      } catch {
        // missing file counts as stale
      }
      if (current !== expected) {
        console.error(`${path.relative(ROOT, file)} is out of date: run \`pnpm db:export-sql\` and commit it.`);
        process.exit(1);
      }
      console.log(`${path.relative(ROOT, file)} is up to date.`);
    }
    return;
  }
  mkdirSync(path.dirname(OUTPUT_FILE), { recursive: true });
  for (const [file, content] of targets) {
    writeFileSync(file, content);
    console.log(`Wrote ${path.relative(ROOT, file)} (${content.length} bytes).`);
  }
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main();
